import{_ as l,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Monthly 2022-02-02","description":"","frontmatter":{"title":"Ceph Developer Monthly 2022-02-02","date":"2022-02-02T00:00:00.000Z","updated":"2022-02-04T00:00:00.000Z","tags":["Ceph","分布式存储","扩展性","指标收集","Prometheus","管理器","蓝图"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Developer_Monthly_2022-02-02.md","filePath":"posts/2022/Ceph_Developer_Monthly_2022-02-02.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Developer_Monthly_2022-02-02.md"};function r(n,e,s,h,p,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p>本次会议主要讨论了Ceph管理器（Manager）和指标收集的扩展性问题，以及如何改进这一过程，以提升Ceph分布式存储系统的高可用性和可扩展性。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>指标收集的扩展性问题</strong>：</p><ul><li>Paul在进行扩展性测试时发现，Ceph管理器在处理大量指标时存在性能瓶颈，每秒需要处理约50MB的数据，对大型集群来说是一个显著的瓶颈。</li><li>会议讨论了如何减轻这一瓶颈，并提出了几种解决方案。</li></ul></li><li><p><strong>改进方案讨论</strong>：</p><ul><li><strong>短期解决方案</strong>： <ul><li>减少需要导出的指标数量，仅导出在Grafana和InfluxDB管理器中实际使用的指标。</li></ul></li><li><strong>长期解决方案</strong>： <ul><li>将指标导出功能从Ceph管理器中分离出来，可能通过每个节点或每个守护进程（demon）的独立导出器来实现。</li><li>讨论了将指标直接从收集点发送到Prometheus，绕过Ceph管理器的可行性。</li><li>提出了在每个节点部署一个独立的导出器（sidecar exporter）来避免在每个服务中嵌入导出逻辑。</li></ul></li></ul></li><li><p><strong>技术细节和挑战</strong>：</p><ul><li>讨论了如何在不同节点和服务之间设置通信，以及如何确保Prometheus能够发现这些导出器。</li><li>提到了使用SQLite作为中间存储，让Prometheus直接从SQLite数据库中抓取数据的可能性。</li><li>讨论了Python处理大量数据时的性能问题，以及是否可以通过将更多逻辑移至C++来优化性能。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续进行原型设计和实验，探索不同的架构方案，如每个守护进程的独立导出器或每个节点的导出器。</li><li>研究如何优化现有的Prometheus模块，减少数据处理量。</li><li>考虑如何支持更细粒度的指标，以满足镜像和复制等新用例的需求。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了需要将指标收集功能从Ceph管理器中分离出来，以提高系统的扩展性和性能。</li><li>同意继续进行原型设计和实验，以确定最佳的长期解决方案。</li></ul><h4 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h4><ul><li>继续进行原型设计和实验，探索不同的架构方案。</li><li>研究如何优化现有的Prometheus模块，减少数据处理量。</li><li>考虑如何支持更细粒度的指标，以满足镜像和复制等新用例的需求。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到了一些技术细节和挑战，需要在后续的实验和设计中进一步探讨和解决。</li><li>需要定期回顾和评估实验结果，以确保解决方案的有效性和可行性。</li></ul><p>本次会议记录涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划，旨在为Ceph存储系统的优化和扩展提供清晰的指导和方向。</p>',11)])])}const c=l(o,[["render",r]]);export{_ as __pageData,c as default};
